versions.variantCss:
.wemd-toc-nav[data-variant="bytedance-toc-clean"] {
  background: var(--wemd-bg-soft);
  border-radius: var(--wemd-border-radius);
  padding: 20px 24px;
  margin: 20px 0 28px 0;
  border-left: 3px solid var(--wemd-primary);
}
.wemd-toc-nav[data-variant="bytedance-toc-clean"] .wemd-component-body {
  padding: 0;
}
.wemd-toc-nav[data-variant="bytedance-toc-clean"] .wemd-component-body .wemd-child-1 {
  color: var(--wemd-primary);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  margin: 0 0 12px 0;
}
.wemd-toc-nav[data-variant="bytedance-toc-clean"] .wemd-component-body .wemd-child-2,
.wemd-toc-nav[data-variant="bytedance-toc-clean"] .wemd-component-body .wemd-child-3,
.wemd-toc-nav[data-variant="bytedance-toc-clean"] .wemd-component-body .wemd-child-4,
.wemd-toc-nav[data-variant="bytedance-toc-clean"] .wemd-component-body .wemd-child-5 {
  color: var(--wemd-text-normal);
  font-size: 15px;
  line-height: 1.8;
  margin: 0;
  padding: 4px 0;
  border-bottom: 1px dashed var(--wemd-border-soft);
}
